inputContract.consumerPredicate:
export function inspectRetainedQualifiedScope(input: {
    config: SemctxConfig;
    graph: RepositoryGraph;
    expectedInputHash: string;
    consumedInputs: ReturnType<typeof captureQualifiedAnalysisInputs>;
    opaqueGraphBinding?: OpaqueGraphBinding;
    checkChanged: boolean;
    retainedCompilerInputs?: ReadonlyMap<string, string>;
}): {
    links: [
        string,
        string
    ][];
    reasons: string[];
    unresolvedImports: {
        path: string;
        specifier: string;
    }[];
    externalModuleSpecifiers: string[];
} {
    const { config } = input;
    const broad = discoverRepository({ ...config, version: 2, selectionMode: "globs-v1", include: ["**/*"], exclude: [], languages: {
            typescript: "on", javascript: "on", python: "on", markdown: "on", sql: "on",
        } }, config);
    const links: [
        string,
        string
    ][] = [];
    const consumed = input.consumedInputs;
    const sourceFiles = consumed.files.filter((file) => /\.[cm]?[jt]sx?$/.test(file.path)).map((file) => ({ relPath: file.path, absPath: resolve(config.repositoryRoot, file.path), content: Buffer.from(file.bytes).toString("utf8") }));
    const compilerInputs = input.retainedCompilerInputs ?? new Map(consumed.files.map((file) => [resolve(config.repositoryRoot, file.path), Buffer.from(file.bytes).toString("utf8")]));
    const token = input.opaqueGraphBinding;
    if (token !== undefined && ownershipBindings.has(token) && token.graphDigest === digestCanonical(input.graph)
        && token.inputHash === consumed.digest && token.inputHash === input.expectedInputHash && !input.checkChanged) {
        registerOpaqueCallbackOwnership(compilerInputs, input.graph, config.repositoryRoot);
    }
    const workspaceNames = new Set<string>();
    const externalPackages = new Map<string, Set<string>>();
    const aliases: string[] = [];
    for (const file of consumed.files.filter((entry) => /(?:^|\/)package\.json$/.test(entry.path) || /(?:^|\/)tsconfig[^/]*\.json$/.test(entry.path))) {
        const parsed = ts.parseConfigFileTextToJson(file.path, Buffer.from(file.bytes).toString("utf8"));
        if (parsed.error !== undefined)
            continue;
        const manifest = parsed.config as {
            name?: unknown;
            dependencies?: Record<string, unknown>;
            devDependencies?: Record<string, unknown>;
            peerDependencies?: Record<string, unknown>;
            optionalDependencies?: Record<string, unknown>;
            compilerOptions?: {
                paths?: Record<string, unknown>;
            };
        };
        if (manifest === null || typeof manifest !== "object")
            continue;
        if (file.path.endsWith("package.json") && typeof manifest.name === "string")
            workspaceNames.add(manifest.name);
        const declared = new Set<string>();
        for (const [name, version] of Object.entries({ ...manifest.dependencies, ...manifest.devDependencies, ...manifest.peerDependencies, ...manifest.optionalDependencies })) {
            if (typeof version === "string" && !/^(?:workspace:|file:|link:)/.test(version))
                declared.add(name);
        }
        if (file.path.endsWith("package.json"))
            externalPackages.set(dirname(resolve(config.repositoryRoot, file.path)), declared);
        aliases.push(...Object.keys(manifest.compilerOptions?.paths ?? {}));
    }
    const isExternal = (specifier: string, from: string): boolean => {
        if (isBuiltin(specifier))
            return true;
        if (specifier.startsWith(".") || specifier.startsWith("/") || aliases.some((alias) => new Bun.Glob(alias).match(specifier)))
            return false;
        const name = specifier.split("/").slice(0, specifier.startsWith("@") ? 2 : 1).join("/");
        if (workspaceNames.has(name))
            return false;
        let directory = dirname(resolve(config.repositoryRoot, from));
        for (;;) {
            if (externalPackages.get(directory)?.has(name))
                return true;
            if (directory === resolve(config.repositoryRoot) || dirname(directory) === directory)
                return false;
            directory = dirname(directory);
        }
    };
    const reasons: string[] = [];
    let extraction: ReturnType<typeof extractTypeScript> = { modules: [], symbols: [], imports: [], calls: [] };
    try {
        extraction = extractTypeScript(sourceFiles.map((file) => file.absPath), config.repositoryRoot, compilerInputs);
    }
    catch (error) {
        if (!(error instanceof Error) || !/^(?:IMPORT|REFERENCE|SOURCE_LINK)_OUTSIDE_REPOSITORY:/.test(error.message))
            throw error;
        reasons.push("DEPENDENCY_SCOPE_OUTSIDE_REPOSITORY");
    }
    for (const entry of extraction.imports)
        if (entry.resolvedRelPath !== undefined)
            links.push([entry.fromRelPath, entry.resolvedRelPath]);
    const byId = new Map(input.graph.nodes.map((node) => [node.id, node.filePath]));
    for (const edge of input.graph.edges) {
        if (!["imports", "exports", "calls", "depends_on"].includes(edge.kind))
            continue;
        const from = byId.get(edge.from);
        const to = byId.get(edge.to);
        if (from !== undefined && to !== undefined)
            links.push([from, to]);
    }
    if (consumed.digest !== input.expectedInputHash)
        reasons.push("DEPENDENCY_SCOPE_INPUT_CHANGED");
    for (const entry of extraction.imports) {
        if (entry.resolvedRelPath === undefined && !isExternal(entry.moduleSpecifier, entry.fromRelPath)) {
            reasons.push(`DEPENDENCY_SCOPE_UNRESOLVED_IMPORT:${entry.fromRelPath}:${entry.moduleSpecifier}`);
        }
    }
    for (const candidate of broad.candidates) {
        if (candidate.reason === "READ_FAILED" || candidate.reason.endsWith("OUTSIDE_REPOSITORY"))
            reasons.push(`DEPENDENCY_SCOPE_UNREADABLE:${candidate.relPath}`);
    }
    for (const file of broad.files)
        if (file.role === "migration" && file.language === "typescript")
            reasons.push(`DEPENDENCY_SCOPE_MIGRATION_SOURCE_UNSUPPORTED:${file.relPath}`);
    for (const source of sourceFiles) {
        if (/\.d\.(?:ts|mts|cts)$/.test(source.relPath))
            reasons.push(`DEPENDENCY_SCOPE_DECLARATION_UNSUPPORTED:${source.relPath}`);
        const ast = ts.createSourceFile(source.relPath, source.content, ts.ScriptTarget.Latest, true);
        const native = inspectNativeModuleBindings(ast);
        if (native.commonJsUnsupported)
            reasons.push(`DEPENDENCY_SCOPE_COMMONJS_UNSUPPORTED:${source.relPath}`);
        if (native.runtimeEvaluationUnsupported)
            reasons.push(`DEPENDENCY_SCOPE_RUNTIME_CODE:${source.relPath}`);
        for (const reference of ts.preProcessFile(source.content, true, true).referencedFiles) {
            if (!compilerInputs.has(resolve(dirname(source.absPath), reference.fileName))) {
                reasons.push(`DEPENDENCY_SCOPE_UNRETAINED_REFERENCE:${source.relPath}:${reference.fileName}`);
            }
        }
        for (const member of native.unmodeledMembers)
            reasons.push(`DEPENDENCY_SCOPE_NATIVE_MODULE_MEMBER_UNSUPPORTED:${source.relPath}:${member}`);
        for (const diagnostic of inspectSourceParsing(source.relPath, source.content))
            reasons.push(`DEPENDENCY_SCOPE_PARSE_FAILED:${source.relPath}:${diagnostic}`);
        for (const diagnostic of inspectModuleConfiguration(source.absPath, config.repositoryRoot, compilerInputs, ast))
            reasons.push(`DEPENDENCY_SCOPE_CONFIGURATION:${source.relPath}:${diagnostic}`);
        const visit = (node: ts.Node): void => {
            if (ts.isCallExpression(node)) {
                const dynamic = node.expression.kind === ts.SyntaxKind.ImportKeyword;
                if (dynamic && (node.arguments.length !== 1 || !ts.isStringLiteral(node.arguments[0]!)))
                    reasons.push(`DEPENDENCY_SCOPE_COMPUTED_IMPORT:${source.relPath}`);
            }
            if ((ts.isImportEqualsDeclaration(node) && ts.isExternalModuleReference(node.moduleReference))
                || (ts.isExportAssignment(node) && node.isExportEquals)) {
                reasons.push(`DEPENDENCY_SCOPE_COMMONJS_UNSUPPORTED:${source.relPath}`);
            }
            if (ts.isImportTypeNode(node))
                reasons.push(`DEPENDENCY_SCOPE_IMPORT_TYPE_UNSUPPORTED:${source.relPath}`);
            if (ts.isWithStatement(node)) {
                reasons.push(`DEPENDENCY_SCOPE_RUNTIME_CODE:${source.relPath}`);
            }
            ts.forEachChild(node, visit);
        };
        visit(ast);
    }
    return { links, reasons,
        externalModuleSpecifiers: [...new Set(extraction.imports.filter(entry => isExternal(entry.moduleSpecifier, entry.fromRelPath)).map(entry => entry.moduleSpecifier))].sort(),
        unresolvedImports: extraction.imports
            .filter((entry) => entry.resolvedRelPath === undefined && !isExternal(entry.moduleSpecifier, entry.fromRelPath))
            .map((entry) => ({ path: entry.fromRelPath, specifier: entry.moduleSpecifier })) };
}

