inputContract.consumerPredicate:
export function assembleRepository(config: SemctxConfig, files: readonly DiscoveredFile[], extraction: TsExtraction, compilerInputs?: CompilerInputSnapshot): AnalysisResult {
    const workspaceLinks = createWorkspaceLinkResolver();
    const tsFiles = files.filter(isTypeScriptSource);
    const analyzedFiles = files.filter((file) => isTypeScriptSource(file) || file.role === "document" || file.role === "migration");
    const selectedPaths = analyzedFiles.map((file) => file.relPath).sort();
    const builder = new DeterministicGraphAssembler(selectedPaths);
    const repoNodeId = repositoryId(config.repositoryRoot);
    builder.node({
        id: repoNodeId,
        kind: "repository",
        name: basename(config.repositoryRoot) || "repository",
        metadata: { root: config.repositoryRoot },
    });
    const roleByRel = new Map<string, DiscoveredFile["role"]>();
    const nodeIdByRel = new Map<string, string>();
    for (const file of files)
        roleByRel.set(file.relPath, file.role);
    for (const file of tsFiles) {
        const isTest = file.role === "test";
        const id = isTest ? testId(file.relPath) : moduleId(file.relPath);
        nodeIdByRel.set(file.relPath, id);
        const javascriptFacts = file.language === "javascript" ? inspectJavaScriptSource(file.absPath, file.content, config.repositoryRoot, compilerInputs, workspaceLinks) : undefined;
        builder.node({
            id,
            kind: isTest ? "test" : "module",
            name: basename(file.relPath),
            filePath: file.relPath,
            ...(javascriptFacts ? { metadata: { staticExports: JSON.stringify(javascriptFacts.staticExports), staticModuleLinks: JSON.stringify(javascriptFacts.staticModuleLinks) } } : {}),
            evidence: [{ filePath: file.relPath, sourceKind: isTest ? "test" : "code" }],
        });
        builder.edge("belongs_to", id, repoNodeId, [{ filePath: file.relPath, sourceKind: "code" }]);
    }
    const byQualified = new Map<string, Map<string, RepositoryNode[]>>();
    const byImportableName = new Map<string, Map<string, RepositoryNode[]>>();
    const markerDeclarations: MarkerDeclaration[] = [];
    for (const sym of groupSymbols(extraction.symbols)) {
        const moduleNodeId = nodeIdByRel.get(sym.relPath);
        const node = builder.node({
            id: sym.id,
            kind: sym.kind,
            name: sym.name,
            filePath: sym.relPath,
            exported: sym.exported,
            evidence: sym.declarations.map((range) => ({
                filePath: sym.relPath,
                startLine: range.startLine,
                endLine: range.endLine,
                sourceKind: "code" as const,
            })),
            metadata: { exported: sym.exported, ...(sym.scope.length > 0 ? { scope: sym.scope.join(".") } : {}) },
        });
        if (moduleNodeId !== undefined) {
            builder.edge("declares", moduleNodeId, sym.id, SYMBOL_EDGE_EVIDENCE(sym.relPath, sym.declarations[0]!.startLine, "code"));
        }
        pushInto(byQualified, sym.relPath, symbolScopePath(sym.scope, sym.name), node);
        if (sym.scope.length === 0)
            pushInto(byImportableName, sym.relPath, sym.name, node);
        for (const marker of sym.markers) {
            markerDeclarations.push({
                tag: marker.tag,
                slug: marker.slug,
                ...(marker.statement !== undefined ? { statement: marker.statement } : {}),
                relPath: sym.relPath,
                startLine: marker.startLine,
            });
        }
        applyCodeMarkers(builder, sym.relPath, sym.markers, sym.id);
    }
    const importEdges: ImportEdgeOccurrence[] = [];
    for (const imp of extraction.imports) {
        const fromId = nodeIdByRel.get(imp.fromRelPath);
        if (fromId === undefined)
            continue;
        if (imp.resolvedRelPath === undefined)
            continue;
        const toId = nodeIdByRel.get(imp.resolvedRelPath);
        if (toId === undefined)
            continue;
        importEdges.push({
            from: fromId,
            to: toId,
            evidence: SYMBOL_EDGE_EVIDENCE(imp.fromRelPath, imp.line, "code"),
            specifier: imp.moduleSpecifier,
        });
    }
    addAggregatedImportEdges(builder, importEdges);
    const callReasons = new Map<string, string[]>();
    const checkLocalCalls = config.version === 2 && config.selectionMode === "qualified-static-v1" && config.analysisProfile === "modelo-suite-static-v1";
    const dynamicTestImports = new Set<string>();
    if (checkLocalCalls && compilerInputs !== undefined)
        for (const file of tsFiles.filter(file => file.role === "test")) {
            const text = compilerInputs.get(file.absPath);
            if (text === undefined)
                continue;
            const source = ts.createSourceFile(file.absPath, text, ts.ScriptTarget.Latest, true);
            const visit = (node: ts.Node): void => {
                if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword && node.arguments.length === 1
                    && ts.isStringLiteral(node.arguments[0]!))
                    dynamicTestImports.add(`${file.relPath}:${source.getLineAndCharacterOfPosition(node.getStart()).line + 1}:${node.arguments[0]!.text}`);
                ts.forEachChild(node, visit);
            };
            visit(source);
        }
    const modeledModules = new Set(extraction.modules);
    const checkCoordinate = (callerPath: string, role: "CALLER" | "CALLEE", path: string | undefined, coordinate: string | undefined): void => {
        if (!checkLocalCalls || path === undefined || coordinate === undefined || !modeledModules.has(path))
            return;
        const matches = byQualified.get(path)?.get(coordinate)?.length ?? 0;
        if (matches === 1)
            return;
        const reason = `QUALIFIED_CALL_COORDINATE_${role}_${matches === 0 ? "MISSING" : "AMBIGUOUS"}:${path}:${coordinate}`;
        const reasons = callReasons.get(callerPath) ?? [];
        if (!reasons.includes(reason))
            reasons.push(reason);
        callReasons.set(callerPath, reasons);
    };
    for (const call of extraction.calls) {
        if (checkLocalCalls && call.callerUnmodeledReason !== undefined && modeledModules.has(call.callerRelPath)) {
            const reasons = callReasons.get(call.callerRelPath) ?? [];
