function statementExecutes(statement: ts.Statement): boolean {
    if (hasModifier(statement, ts.SyntaxKind.DeclareKeyword))
        return false;
    if (ts.isFunctionDeclaration(statement) || ts.isInterfaceDeclaration(statement) || ts.isTypeAliasDeclaration(statement))
